-- =====================================================================
-- 0003_admin_management_and_redirects.sql
-- =====================================================================

-- =====================================================================
-- Bestech catalogue — 0003
--
-- Closes two gaps that would each have required a developer call-out,
-- which is exactly what this project is meant to avoid.
--
--   A. Staff management. 0001 enabled RLS on `admins` and created no
--      policy, which locks the table to attackers AND to the owner.
--      Adding a colleague or removing someone who left meant opening
--      the Supabase dashboard and running SQL by hand.
--
--   B. URL history. Renaming a product or re-organising the category
--      tree changes URLs. With no prices and no cart, organic search is
--      the whole funnel, so a silently broken URL is lost business.
--      Nothing recorded the change, so no redirect could be emitted.
-- =====================================================================


-- ---------------------------------------------------------------------
-- A. Staff management
-- ---------------------------------------------------------------------

-- Admins can see the staff list. Still invisible to everyone else:
-- there is deliberately no insert/update/delete policy, so the only way
-- to change this table through the API is the two guarded functions
-- below, which enforce rules a raw policy cannot.
create policy admins_read on admins
  for select using (is_admin());

-- Grant access by email. The person must already have signed in once
-- (so an auth user exists) — we never create accounts here.
create or replace function add_admin(p_email text)
  returns uuid
  language plpgsql security definer set search_path = public, auth as $fn$
declare
  target uuid;
begin
  if not is_admin() then
    raise exception 'only an administrator may add another administrator';
  end if;

  select id into target from auth.users
   where lower(email) = lower(trim(p_email)) limit 1;

  if target is null then
    raise exception 'no account exists for %. Ask them to sign in once first, then add them.', p_email;
  end if;

  insert into admins (user_id, email) values (target, lower(trim(p_email)))
    on conflict (user_id) do nothing;

  return target;
end
$fn$;

-- Revoke access. Refuses to remove the last administrator, because an
-- empty admins table locks everyone out of the site permanently and can
-- only be undone from the Supabase dashboard.
create or replace function remove_admin(p_user_id uuid)
  returns void
  language plpgsql security definer set search_path = public as $fn$
begin
  if not is_admin() then
    raise exception 'only an administrator may remove an administrator';
  end if;

  if (select count(*) from admins) <= 1 then
    raise exception 'cannot remove the last administrator — add someone else first';
  end if;

  delete from admins where user_id = p_user_id;
end
$fn$;

revoke all on function add_admin(text)    from public, anon;
revoke all on function remove_admin(uuid) from public, anon;
grant execute on function add_admin(text)    to authenticated;
grant execute on function remove_admin(uuid) to authenticated;


-- ---------------------------------------------------------------------
-- B. URL history, so links never rot
--
-- Every path this site has ever served is recorded the moment it stops
-- being current. The build reads this table and emits a small stub page
-- at each retired path carrying a canonical link to the live one, so an
-- old Google result or a WhatsApp link from two years ago still lands
-- somewhere useful instead of on a 404.
--
-- Nobody has to know what a 301 is: it is a side effect of renaming.
-- ---------------------------------------------------------------------
create table path_history (
  old_path    text primary key,
  new_path    text not null,
  kind        text not null check (kind in ('product', 'category')),
  recorded_at timestamptz not null default now()
);

alter table path_history enable row level security;
create policy path_history_read on path_history for select using (true);
create policy path_history_write on path_history
  for all to authenticated using (is_admin()) with check (is_admin());

-- Record a move, and re-point any older entries that led to the old
-- location so a chain of renames (A->B, then B->C) always resolves in
-- ONE hop to the current page rather than bouncing through history.
create or replace function record_path_move(p_old text, p_new text, p_kind text)
  returns void
  language plpgsql as $fn$
begin
  if p_old is null or p_new is null or p_old = p_new then return; end if;

  insert into path_history (old_path, new_path, kind)
       values (p_old, p_new, p_kind)
  on conflict (old_path) do update set new_path = excluded.new_path,
                                       recorded_at = now();

  -- Collapse chains.
  update path_history set new_path = p_new, recorded_at = now()
   where new_path = p_old;

  -- If the path has been reused, it is no longer a redirect source.
  delete from path_history where old_path = p_new;
end
$fn$;

create or replace function products_track_slug() returns trigger
  language plpgsql as $fn$
begin
  perform record_path_move('/product/' || old.slug, '/product/' || new.slug, 'product');
  return null;
end
$fn$;

create trigger products_slug_history
  after update of slug on products
  for each row when (old.slug is distinct from new.slug)
  execute function products_track_slug();

create or replace function categories_track_path() returns trigger
  language plpgsql as $fn$
begin
  perform record_path_move('/c/' || old.path, '/c/' || new.path, 'category');
  return null;
end
$fn$;

-- Note this fires for descendants too: 0001's path trigger cascades a
-- re-parent down the branch, so every moved child records its own
-- redirect automatically.
create trigger categories_path_history
  after update of path on categories
  for each row when (old.path is distinct from new.path)
  execute function categories_track_path();


-- =====================================================================
-- 0004_image_storage.sql
-- =====================================================================

-- =====================================================================
-- Bestech catalogue — 0004
--
-- Somewhere to put the photographs.
--
-- ~250 best sellers, photographed in-house, at three derivatives each
-- = roughly 750 files. They are written once and read constantly, which
-- is the easiest possible storage workload; the only thing that matters
-- is that reads are public and cheap, and that writes are locked to
-- staff.
--
-- The bucket is PUBLIC on purpose. These are product photographs for a
-- catalogue whose whole job is to be found — signed URLs would add an
-- API round trip in front of every image on every page and break CDN
-- caching, in exchange for protecting pictures we want indexed.
--
-- Portability note: the database stores a KEY ("products/hg-id13/1"),
-- never a URL, and lib/images.mjs composes the URL from one environment
-- variable. Moving these files to Cloudflare R2 or any other object
-- store is therefore a bucket copy plus a changed variable — no rows to
-- rewrite, which is why this migration can safely start on Supabase
-- Storage today without committing the project to it.
-- =====================================================================

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'product-images',
  'product-images',
  true,
  -- 6MB. The admin resizes and re-encodes to WebP in the browser before
  -- anything is uploaded, so a derivative is tens of kilobytes; this cap
  -- exists only to stop a misconfigured client streaming a raw 40MB file.
  6291456,
  array['image/webp', 'image/jpeg', 'image/png']
)
on conflict (id) do update
  set public             = excluded.public,
      file_size_limit    = excluded.file_size_limit,
      allowed_mime_types = excluded.allowed_mime_types;


-- Anyone may read. This is what makes a plain <img src> work with no
-- token, no expiry and no API call in front of it.
create policy "product images are publicly readable"
  on storage.objects for select
  using (bucket_id = 'product-images');

-- Only allowlisted staff may write, using the same is_admin() check that
-- guards every other table. One definition of "staff", not two.
create policy "admins may upload product images"
  on storage.objects for insert to authenticated
  with check (bucket_id = 'product-images' and is_admin());

create policy "admins may replace product images"
  on storage.objects for update to authenticated
  using (bucket_id = 'product-images' and is_admin())
  with check (bucket_id = 'product-images' and is_admin());

create policy "admins may delete product images"
  on storage.objects for delete to authenticated
  using (bucket_id = 'product-images' and is_admin());


-- =====================================================================
-- 0005_publishing.sql
-- =====================================================================

-- =====================================================================
-- Bestech catalogue — 0005
--
-- Publishing.
--
-- The public site is static files, so "publish" means "rebuild and
-- redeploy". The obvious way to let staff trigger that is to put a
-- deploy-hook URL in the admin page and POST it from the browser.
--
-- That is wrong, and worth spelling out so nobody re-adds it later:
-- the admin is a static page served to anyone who asks for it, so a
-- URL inside it is public. A deploy hook is a bearer credential — the
-- URL IS the authorisation. Publishing it means a stranger can trigger
-- unlimited builds, which costs money on every host that bills them.
--
-- Instead, publishing is a ROW. An administrator (checked by the same
-- RLS used everywhere else) inserts a request; CI reads the queue,
-- rebuilds, and marks it done. The deploy credential stays in CI where
-- it belongs, never reaching a browser.
--
-- The side benefit is a permanent record of who published what and
-- when, which is the first thing anyone wants when a wrong price list
-- goes live.
-- =====================================================================

create table publish_requests (
  id            bigint generated always as identity primary key,
  requested_by  uuid references auth.users(id) on delete set null,
  requested_at  timestamptz not null default now(),
  note          text not null default '',
  started_at    timestamptz,
  completed_at  timestamptz,
  ok            boolean,
  detail        text not null default ''
);

create index publish_requests_pending_idx
  on publish_requests (requested_at)
  where completed_at is null;

alter table publish_requests enable row level security;

-- Staff can see the history (useful: "did my change go live?").
create policy publish_requests_read on publish_requests
  for select using (is_admin());

-- Nobody writes directly. Requesting goes through the function below so
-- the queue cannot be flooded, and CI updates rows with the service
-- role, which bypasses RLS.
create or replace function request_publish(p_note text default '')
  returns publish_requests
  language plpgsql security definer set search_path = public as $fn$
declare
  pending publish_requests;
begin
  if not is_admin() then
    raise exception 'only an administrator may publish';
  end if;

  -- Coalesce. Ten edits in a row should be one rebuild, not ten: the
  -- build always renders the current state of the database, so a second
  -- request while one is still queued adds nothing but cost.
  select * into pending from publish_requests
   where completed_at is null
   order by requested_at asc limit 1;

  if found then
    return pending;
  end if;

  insert into publish_requests (requested_by, note)
       values (auth.uid(), coalesce(p_note, ''))
    returning * into pending;

  return pending;
end
$fn$;

revoke all on function request_publish(text) from public, anon;
grant execute on function request_publish(text) to authenticated;

-- What the admin polls to show "queued" / "building" / "live".
create or replace function publish_status()
  returns table (state text, requested_at timestamptz, completed_at timestamptz, ok boolean, detail text)
  language sql stable security definer set search_path = public as $fn$
  select
    case
      when r.id is null            then 'idle'
      when r.started_at is null    then 'queued'
      when r.completed_at is null  then 'building'
      else 'done'
    end,
    r.requested_at, r.completed_at, r.ok, r.detail
  from (
    select * from publish_requests
     order by requested_at desc limit 1
  ) r
  where is_admin();
$fn$;

revoke all on function publish_status() from public, anon;
grant execute on function publish_status() to authenticated;


-- =====================================================================
-- 0006_category_taxonomy.sql
-- =====================================================================

-- =====================================================================
-- Bestech catalogue — 0006
--
-- The category tree, and a uniqueness bug in 0001.
--
-- WHY NOW, before the client's catalogue has arrived: the importer
-- deliberately refuses to create categories as a side effect of
-- importing a product — guessing a taxonomy from a spreadsheet is how
-- you end up with "Drills", "drills" and "Drill" as three siblings. So
-- until a tree exists, NO product file can be imported at all. This is
-- required work, not a guess at decoration.
--
-- The shape follows how the trade actually shops: by tool type first
-- (dewalt.com), not by brand. A buyer wants a 13mm impact drill and
-- does not care who made it until they are comparing two.
--
-- It is a STARTING POINT, not a decision. Every name here is editable
-- in the admin, and the real catalogue will add and rename branches.
-- Renames are safe: the path trigger from 0001 cascades to children,
-- and 0003 records a redirect for every moved URL automatically.
-- =====================================================================


-- ---------------------------------------------------------------------
-- First, a real bug in 0001.
--
-- `unique (parent_id, slug)` does NOT constrain top-level categories,
-- because in standard SQL two NULLs are not equal — so any number of
-- root categories could share a slug. Since a root category's `path`
-- IS its slug, that means two categories resolving to the same URL,
-- and a build where one silently overwrites the other's page.
--
-- `path` is the thing that must actually be unique: it is what the URL
-- is built from. Constrain that directly and both cases are covered.
-- ---------------------------------------------------------------------
create unique index categories_path_unique on categories (path);


-- ---------------------------------------------------------------------
-- Top level
--
-- path and depth are NOT set here. The trigger from 0001 derives them
-- from the parent chain, so they can never drift from parent_id.
-- ---------------------------------------------------------------------
insert into categories (division_id, parent_id, slug, name, sort)
select d.id, null, v.slug, v.name, v.sort
from (values
  ('drills',            'Drills',                     10),
  ('grinders',          'Grinders',                   20),
  ('saws',              'Saws',                       30),
  ('sanders-polishers', 'Sanders & Polishers',        40),
  ('planers-routers',   'Planers & Routers',          50),
  ('demolition',        'Demolition & Breakers',      60),
  ('welding',           'Welding & Cutting',          70),
  ('air-tools',         'Air Tools & Compressors',    80),
  ('generators',        'Generators',                 90),
  ('concrete',          'Concrete & Masonry',        100),
  ('garden',            'Garden & Outdoor',          110),
  ('cleaning',          'Cleaning Equipment',        120),
  ('measuring',         'Measuring & Levelling',     130),
  ('workshop',          'Workshop Machinery',        140),
  ('accessories',       'Accessories & Consumables', 150)
) as v(slug, name, sort)
cross join divisions d
where d.slug = 'power-tools-machinery'
on conflict do nothing;

insert into categories (division_id, parent_id, slug, name, sort)
select d.id, null, v.slug, v.name, v.sort
from (values
  ('surface-pumps',     'Surface Pumps',              10),
  ('submersible-pumps', 'Submersible Pumps',          20),
  ('pressure-systems',  'Pressure Systems',           30),
  ('agricultural',      'Agricultural & Irrigation',  40),
  ('pump-accessories',  'Pump Accessories',           50)
) as v(slug, name, sort)
cross join divisions d
where d.slug = 'water-pumps'
on conflict do nothing;


-- ---------------------------------------------------------------------
